  + material : string
}

class DriveSystem {
}

class Motor {
}

class Controller {
  + state : ControllerState
}

class Battery {
  + energyWh : float
}

class BasicController {}

class AdvancedController {
  + nextInspectionDate : date
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
